-- ============================================================
-- Title and Description of every draft watch assigned to a given
-- ReferenceNumberId. Reuses ##referenceNumbers (same input table as the
-- ReferenceNumberId-only query above) -- fill it in first.
-- ============================================================
IF OBJECT_ID('tempdb..#WatchTitleDesc') IS NOT NULL DROP TABLE #WatchTitleDesc;
SELECT
    wd.ReferenceNumberId,
    wd.WatchId,
    wd.Title,
    wd.Description
INTO #WatchTitleDesc
FROM ##referenceNumbers AS rn WITH (NOLOCK)
INNER JOIN dbo.tblWatch_d AS wd WITH (NOLOCK) ON wd.ReferenceNumberId = rn.ReferenceNumberId;

SELECT *
FROM #WatchTitleDesc WITH (NOLOCK)
ORDER BY ReferenceNumberId, WatchId;


-- ============================================================
-- Extract "W-tokens" from Description: a word starting with W/w,
-- followed by 1-7 more characters (whole token 2-8 chars), where those
-- remaining characters are NOT pure letters -- i.e. must contain at
-- least one digit. "Must contain a digit" is used as the one check:
-- a remainder that's all letters has zero digits and gets excluded by
-- this same condition, so no separate "not all letters" check is needed.
-- Examples that MATCH: we234, wsd34567, W1234567 (pure digits after W
-- also pass -- a very common real reference pattern, e.g. "W2001583").
-- Examples that DON'T match: "Watch", "When" (remainder is all letters,
-- so no digit present -> excluded); a token with >7 chars after the W.
--
-- Only rows (watches) with at least one qualifying match are returned --
-- one output row PER MATCH, so a Description with 2 different qualifying
-- tokens produces 2 rows, each with its own matched word + context.
--
-- Context column = the 5 words before + the matched word itself + the
-- 5 words after, joined back together with spaces (clipped at the start/
-- end of the description if fewer than 5 words exist on either side).
--
-- Word splitting is done via OPENJSON (not STRING_SPLIT's ordinal
-- option, which needs SQL Server 2022+) so this works on older SQL
-- Server versions too; splits on single spaces only.
-- Embedded/trailing punctuation on a candidate word (commas, periods,
-- parentheses, etc.) is stripped before pattern-checking, so "W1234567,"
-- in running text still matches as "W1234567".
-- ============================================================

-- Step 1: stage matching watches' Description (non-blank only).
IF OBJECT_ID('tempdb..#WatchDescW') IS NOT NULL DROP TABLE #WatchDescW;
SELECT
    wd.ReferenceNumberId,
    wd.WatchId,
    wd.Description
INTO #WatchDescW
FROM ##referenceNumbers AS rn WITH (NOLOCK)
INNER JOIN dbo.tblWatch_d AS wd WITH (NOLOCK) ON wd.ReferenceNumberId = rn.ReferenceNumberId
WHERE wd.Description IS NOT NULL
  AND LTRIM(RTRIM(wd.Description)) <> '';

-- Step 2: tokenize each Description into words with their position
-- (0-based array index from OPENJSON).
IF OBJECT_ID('tempdb..#DescWords') IS NOT NULL DROP TABLE #DescWords;
SELECT
    d.ReferenceNumberId,
    d.WatchId,
    CAST(j.[key] AS INT) AS WordOrdinal,
    j.[value] AS Word
INTO #DescWords
FROM #WatchDescW AS d
CROSS APPLY OPENJSON(
    '["' + REPLACE(STRING_ESCAPE(d.Description, 'json'), ' ', '","') + '"]'
) AS j
WHERE LTRIM(RTRIM(j.[value])) <> '';

-- Step 3: find qualifying W-tokens (strip trailing/embedded punctuation
-- first, then apply the length + digit-present checks).
IF OBJECT_ID('tempdb..#WMatches') IS NOT NULL DROP TABLE #WMatches;
;WITH Cleaned AS (
    SELECT
        ReferenceNumberId,
        WatchId,
        WordOrdinal,
        Word,
        CleanWord = LEFT(
            Word,
            CASE
                WHEN PATINDEX('%[^a-zA-Z0-9]%', Word) = 0 THEN LEN(Word)
                ELSE PATINDEX('%[^a-zA-Z0-9]%', Word) - 1
            END
        )
    FROM #DescWords
)
SELECT
    ReferenceNumberId,
    WatchId,
    WordOrdinal,
    CleanWord AS MatchedWord
INTO #WMatches
FROM Cleaned
WHERE LEN(CleanWord) BETWEEN 2 AND 8
  AND UPPER(LEFT(CleanWord, 1)) = 'W'
  AND SUBSTRING(CleanWord, 2, LEN(CleanWord) - 1) LIKE '%[0-9]%';

-- Step 4: build the 5-before / 5-after context per match, and return
-- only these matched rows.
SELECT
    m.ReferenceNumberId,
    m.WatchId,
    m.MatchedWord,
    STRING_AGG(dw.Word, ' ') WITHIN GROUP (ORDER BY dw.WordOrdinal) AS Context
FROM #WMatches AS m
INNER JOIN #DescWords AS dw
    ON dw.ReferenceNumberId = m.ReferenceNumberId
   AND dw.WatchId = m.WatchId
   AND dw.WordOrdinal BETWEEN m.WordOrdinal - 5 AND m.WordOrdinal + 5
GROUP BY m.ReferenceNumberId, m.WatchId, m.WordOrdinal, m.MatchedWord
ORDER BY m.ReferenceNumberId, m.WatchId, m.WordOrdinal;


-- ============================================================
-- For a list of plain reference number TEXT values, flag where each one
-- was actually found, in STRICT priority order (first match wins, lower
-- priority sources are not even reported once a higher one hits):
--   1. Catalog     -> dbo.tbl_CAT_Catalog_d.ReferenceNumber (EWMaster) --
--      direct/exact match (Catalog's ReferenceNumber is a clean single
--      value, not embedded text).
--   2. EveryWatch  -> EveryWatch.dbo.tblReferenceNumber.ReferenceNumber --
--      NOT a direct match: this field can hold the ref embedded with
--      other text ("1234/wr234565", "1234 wr234565", "wr234565 1234"),
--      so it's tokenized on space AND slash (slash normalized to space
--      first) and matched as an exact TOKEN, not a substring (a plain
--      LIKE '%ref%' would risk false positives, e.g. ref "234" matching
--      inside "1234"). Per your stated rule, a Catalog match is always
--      also present here, so the SAME lookup's ReferenceNumberId is used
--      for both the Catalog row and the EveryWatch-only row.
--   3. RawRef      -> EveryWatch.dbo.tblWatch_d.RawReferenceNumber --
--      only checked if NEITHER of the above matched. Same token-based
--      extraction as EveryWatch (space/slash delimited), not a direct
--      match. Returns the TOP 5 WatchIds (comma-separated) whose
--      RawReferenceNumber tokenizes to this ref.
--   4. NotFound    -> none of the above.
--
-- Output columns:
--   CatalogId          -- populated only when Source = 'Catalog'
--   ReferenceNumberId  -- populated when Source = 'Catalog' or 'EveryWatch'
--   WatchIds           -- populated only when Source = 'RawRef' (top 5, comma-separated)
--
-- PERFORMANCE NOTE: tblReferenceNumber/tblWatch_d are tokenized in full
-- (every row, split into words) since there's no way to search "does this
-- field contain this exact token" without scanning the text -- this is a
-- full scan of both tables, done ONCE regardless of how many reference
-- numbers are in ##refNumbersCheck, then joined (not a full scan PER
-- input reference). Still, expect this to take real time on large tables.
--
-- Rename/replace ##refNumbersCheck below to your actual existing temp
-- table if it's named differently.
-- ============================================================

IF OBJECT_ID('tempdb..##refNumbersCheck') IS NOT NULL DROP TABLE ##refNumbersCheck;
CREATE TABLE ##refNumbersCheck
(
    ReferenceNumber NVARCHAR(200)
);
-- INSERT INTO ##refNumbersCheck (ReferenceNumber) VALUES ('116610LN'), ('wr234565');

-- Step 1: tokenize EveryWatch.tblReferenceNumber and tblWatch_d.RawReferenceNumber
-- (full-table, one-time; '/' normalized to a space before splitting on space).
IF OBJECT_ID('tempdb..#EveryWatchTokens') IS NOT NULL DROP TABLE #EveryWatchTokens;
SELECT DISTINCT
    tr.ReferenceNumberId,
    UPPER(LTRIM(RTRIM(tok.value))) AS Token
INTO #EveryWatchTokens
FROM EveryWatch.dbo.tblReferenceNumber AS tr WITH (NOLOCK)
CROSS APPLY STRING_SPLIT(REPLACE(ISNULL(tr.ReferenceNumber, N''), '/', ' '), ' ') AS tok
WHERE LTRIM(RTRIM(tok.value)) <> '';

CREATE INDEX IX_EveryWatchTokens_Token ON #EveryWatchTokens (Token);

IF OBJECT_ID('tempdb..#RawRefTokens') IS NOT NULL DROP TABLE #RawRefTokens;
SELECT DISTINCT
    wd.WatchId,
    UPPER(LTRIM(RTRIM(tok.value))) AS Token
INTO #RawRefTokens
FROM EveryWatch.dbo.tblWatch_d AS wd WITH (NOLOCK)
CROSS APPLY STRING_SPLIT(REPLACE(ISNULL(wd.RawReferenceNumber, N''), '/', ' '), ' ') AS tok
WHERE LTRIM(RTRIM(tok.value)) <> '';

CREATE INDEX IX_RawRefTokens_Token ON #RawRefTokens (Token);

-- Step 2: match each input reference against each source, priority order.
;WITH CatalogMatch AS (
    SELECT
        r.ReferenceNumber,
        cd.CatalogId,
        ROW_NUMBER() OVER (PARTITION BY r.ReferenceNumber ORDER BY cd.CatalogId) AS rn
    FROM ##refNumbersCheck AS r WITH (NOLOCK)
    INNER JOIN dbo.tbl_CAT_Catalog_d AS cd WITH (NOLOCK)
        ON UPPER(LTRIM(RTRIM(cd.ReferenceNumber))) = UPPER(LTRIM(RTRIM(r.ReferenceNumber)))
),
EveryWatchMatch AS (
    SELECT
        r.ReferenceNumber,
        ewt.ReferenceNumberId,
        ROW_NUMBER() OVER (PARTITION BY r.ReferenceNumber ORDER BY ewt.ReferenceNumberId) AS rn
    FROM ##refNumbersCheck AS r WITH (NOLOCK)
    INNER JOIN #EveryWatchTokens AS ewt
        ON ewt.Token = UPPER(LTRIM(RTRIM(r.ReferenceNumber)))
),
RawRefMatch AS (
    SELECT
        r.ReferenceNumber,
        rrt.WatchId,
        ROW_NUMBER() OVER (PARTITION BY r.ReferenceNumber ORDER BY rrt.WatchId) AS rn
    FROM ##refNumbersCheck AS r WITH (NOLOCK)
    INNER JOIN #RawRefTokens AS rrt
        ON rrt.Token = UPPER(LTRIM(RTRIM(r.ReferenceNumber)))
),
RawRefTop5 AS (
    SELECT
        ReferenceNumber,
        STRING_AGG(CAST(WatchId AS VARCHAR(20)), ',') WITHIN GROUP (ORDER BY WatchId) AS WatchIds
    FROM RawRefMatch
    WHERE rn <= 5
    GROUP BY ReferenceNumber
)
SELECT
    r.ReferenceNumber,
    Source = CASE
        WHEN cm.CatalogId IS NOT NULL THEN 'Catalog'
        WHEN ewm.ReferenceNumberId IS NOT NULL THEN 'EveryWatch'
        WHEN rrt5.WatchIds IS NOT NULL THEN 'RawRef'
        ELSE 'NotFound'
    END,
    CatalogId = cm.CatalogId,
    ReferenceNumberId = ewm.ReferenceNumberId,
    WatchIds = CASE
        WHEN cm.CatalogId IS NULL AND ewm.ReferenceNumberId IS NULL THEN rrt5.WatchIds
        ELSE NULL
    END
INTO #RefSourceFlags
FROM ##refNumbersCheck AS r WITH (NOLOCK)
LEFT JOIN CatalogMatch AS cm ON cm.ReferenceNumber = r.ReferenceNumber AND cm.rn = 1
LEFT JOIN EveryWatchMatch AS ewm ON ewm.ReferenceNumber = r.ReferenceNumber AND ewm.rn = 1
LEFT JOIN RawRefTop5 AS rrt5 ON rrt5.ReferenceNumber = r.ReferenceNumber;

SELECT * FROM #RefSourceFlags ORDER BY ReferenceNumber;


-- ============================================================
-- Using #RefSourceFlags, pull watch data (DialColor, CaseMaterial,
-- ModelName most-occurring, one PublishWatchId, up to 5 ImageUrls) per
-- ReferenceNumber. NotFound rows are excluded automatically -- each
-- branch below filters to its own Source, so a NotFound row never gets
-- pulled into any of the three branches.
--
--   Catalog     -> MasterDB catalog-side tables directly (one catalog
--                  row, so no "voting" needed -- just that catalog's
--                  tagged dial colors/case materials/model). ONE image
--                  only (the catalog's primary image). PublishWatchId
--                  skipped (NULL) -- there's no watch here, just a
--                  catalog record.
--   EveryWatch  -> ReferenceNumberId -> every tblWatch_d row for it ->
--                  most-occurring dial/case/model across ALL of them,
--                  PublishWatchId = any one (the smallest WatchId's),
--                  up to 5 image URLs (one per watch, smallest WatchIds
--                  first).
--   RawRef      -> reuses the WatchIds already capped at 5 from
--                  #RefSourceFlags (computed during the flagging step) --
--                  most-occurring dial/case/model across just those
--                  (<=5) watches, PublishWatchId = any one, one image
--                  per watch (<=5 total).
-- ============================================================

-- ---------- EveryWatch branch (now also covers Catalog-sourced refs) ----------
-- Catalog-sourced refs already have a ReferenceNumberId too (per the rule
-- that a Catalog match is always also present in tblReferenceNumber), so
-- they're pulled in here alongside true EveryWatch-sourced refs and
-- treated identically -- no separate MasterDB catalog-side lookup anymore.
IF OBJECT_ID('tempdb..#EWWatchList') IS NOT NULL DROP TABLE #EWWatchList;
SELECT
    f.ReferenceNumber,
    wd.WatchId
INTO #EWWatchList
FROM #RefSourceFlags AS f WITH (NOLOCK)
INNER JOIN dbo.tblWatch_d AS wd WITH (NOLOCK) ON wd.ReferenceNumberId = f.ReferenceNumberId
WHERE f.Source IN ('Catalog', 'EveryWatch');

IF OBJECT_ID('tempdb..#EWWatchCore') IS NOT NULL DROP TABLE #EWWatchCore;
SELECT
    wl.ReferenceNumber,
    wd.WatchId,
    wd.ModelId,
    m.ModelName
INTO #EWWatchCore
FROM #EWWatchList AS wl WITH (NOLOCK)
INNER JOIN dbo.tblWatch_d AS wd WITH (NOLOCK) ON wd.WatchId = wl.WatchId
LEFT JOIN dbo.tblModel AS m WITH (NOLOCK) ON m.ModelId = wd.ModelId;

IF OBJECT_ID('tempdb..#EWWatchTop5') IS NOT NULL DROP TABLE #EWWatchTop5;
;WITH Ranked AS (
    SELECT
        ReferenceNumber, WatchId,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY WatchId ASC) AS rn
    FROM #EWWatchCore
)
SELECT
    r.ReferenceNumber,
    r.WatchId,
    r.rn,
    PrimaryImage = (
        SELECT TOP 1 COALESCE(ma.Original, ma.Preview1366, ma.Preview768, ma.Preview480, ma.Preview320)
        FROM dbo.tblMediaAsset_d AS ma WITH (NOLOCK)
        WHERE ma.WatchId = r.WatchId AND (ma.IsDeleted = 0 OR ma.IsDeleted IS NULL)
        ORDER BY ma.IsPrimary DESC, ma.MediaAssetId ASC
    ),
    PublishWatchId = (
        SELECT TOP 1 tw.WatchId FROM dbo.tblWatch AS tw WITH (NOLOCK) WHERE tw.WatchListingDraftId = r.WatchId
    )
INTO #EWWatchTop5
FROM Ranked AS r
WHERE r.rn <= 5;

IF OBJECT_ID('tempdb..#EWColorVotes') IS NOT NULL DROP TABLE #EWColorVotes;
SELECT t.ReferenceNumber, c.ColorName, COUNT(*) AS VoteCount
INTO #EWColorVotes
FROM #EWWatchCore AS t WITH (NOLOCK)
JOIN dbo.tblWatchToDialColor_d AS wdcd WITH (NOLOCK) ON wdcd.WatchId = t.WatchId
JOIN dbo.tblColor AS c WITH (NOLOCK) ON c.ColorId = wdcd.DialColorId
GROUP BY t.ReferenceNumber, c.ColorName;

IF OBJECT_ID('tempdb..#EWMaterialVotes') IS NOT NULL DROP TABLE #EWMaterialVotes;
SELECT t.ReferenceNumber, cm.CaseMaterialName, COUNT(*) AS VoteCount
INTO #EWMaterialVotes
FROM #EWWatchCore AS t WITH (NOLOCK)
JOIN dbo.tblWatchToCaseMaterial_d AS wcmd WITH (NOLOCK) ON wcmd.WatchId = t.WatchId
JOIN dbo.tblCaseMaterial AS cm WITH (NOLOCK) ON cm.CaseMaterialId = wcmd.CaseMaterialId
GROUP BY t.ReferenceNumber, cm.CaseMaterialName;

IF OBJECT_ID('tempdb..#EWModelVotes') IS NOT NULL DROP TABLE #EWModelVotes;
SELECT t.ReferenceNumber, t.ModelName, COUNT(*) AS VoteCount
INTO #EWModelVotes
FROM #EWWatchCore AS t WITH (NOLOCK)
WHERE t.ModelName IS NOT NULL
GROUP BY t.ReferenceNumber, t.ModelName;

IF OBJECT_ID('tempdb..#EveryWatchBranch') IS NOT NULL DROP TABLE #EveryWatchBranch;
;WITH TopColor AS (
    SELECT ReferenceNumber, ColorName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, ColorName ASC) AS rn
    FROM #EWColorVotes
),
TopMaterial AS (
    SELECT ReferenceNumber, CaseMaterialName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, CaseMaterialName ASC) AS rn
    FROM #EWMaterialVotes
),
TopModel AS (
    SELECT ReferenceNumber, ModelName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, ModelName ASC) AS rn
    FROM #EWModelVotes
),
AnyWatch AS (
    SELECT ReferenceNumber, PublishWatchId
    FROM #EWWatchTop5
    WHERE rn = 1
)
SELECT
    t.ReferenceNumber,
    DialColor = MAX(tc.ColorName),
    CaseMaterial = MAX(tm.CaseMaterialName),
    ModelName = MAX(tmo.ModelName),
    PublishWatchId = MAX(aw.PublishWatchId),
    Images = STRING_AGG(t.PrimaryImage, ', ') WITHIN GROUP (ORDER BY t.WatchId)
INTO #EveryWatchBranch
FROM #EWWatchTop5 AS t WITH (NOLOCK)
LEFT JOIN TopColor AS tc ON tc.ReferenceNumber = t.ReferenceNumber AND tc.rn = 1
LEFT JOIN TopMaterial AS tm ON tm.ReferenceNumber = t.ReferenceNumber AND tm.rn = 1
LEFT JOIN TopModel AS tmo ON tmo.ReferenceNumber = t.ReferenceNumber AND tmo.rn = 1
LEFT JOIN AnyWatch AS aw ON aw.ReferenceNumber = t.ReferenceNumber
GROUP BY t.ReferenceNumber;

-- ---------- RawRef branch ----------
IF OBJECT_ID('tempdb..#RRWatchList') IS NOT NULL DROP TABLE #RRWatchList;
SELECT
    f.ReferenceNumber,
    TRY_CAST(LTRIM(RTRIM(s.value)) AS BIGINT) AS WatchId
INTO #RRWatchList
FROM #RefSourceFlags AS f WITH (NOLOCK)
CROSS APPLY STRING_SPLIT(f.WatchIds, ',') AS s
WHERE f.Source = 'RawRef'
  AND TRY_CAST(LTRIM(RTRIM(s.value)) AS BIGINT) IS NOT NULL;

IF OBJECT_ID('tempdb..#RRWatchCore') IS NOT NULL DROP TABLE #RRWatchCore;
SELECT
    wl.ReferenceNumber,
    wd.WatchId,
    wd.ModelId,
    m.ModelName,
    PrimaryImage = (
        SELECT TOP 1 COALESCE(ma.Original, ma.Preview1366, ma.Preview768, ma.Preview480, ma.Preview320)
        FROM dbo.tblMediaAsset_d AS ma WITH (NOLOCK)
        WHERE ma.WatchId = wd.WatchId AND (ma.IsDeleted = 0 OR ma.IsDeleted IS NULL)
        ORDER BY ma.IsPrimary DESC, ma.MediaAssetId ASC
    ),
    PublishWatchId = (
        SELECT TOP 1 tw.WatchId FROM dbo.tblWatch AS tw WITH (NOLOCK) WHERE tw.WatchListingDraftId = wd.WatchId
    )
INTO #RRWatchCore
FROM #RRWatchList AS wl WITH (NOLOCK)
INNER JOIN dbo.tblWatch_d AS wd WITH (NOLOCK) ON wd.WatchId = wl.WatchId
LEFT JOIN dbo.tblModel AS m WITH (NOLOCK) ON m.ModelId = wd.ModelId;

IF OBJECT_ID('tempdb..#RRColorVotes') IS NOT NULL DROP TABLE #RRColorVotes;
SELECT t.ReferenceNumber, c.ColorName, COUNT(*) AS VoteCount
INTO #RRColorVotes
FROM #RRWatchCore AS t WITH (NOLOCK)
JOIN dbo.tblWatchToDialColor_d AS wdcd WITH (NOLOCK) ON wdcd.WatchId = t.WatchId
JOIN dbo.tblColor AS c WITH (NOLOCK) ON c.ColorId = wdcd.DialColorId
GROUP BY t.ReferenceNumber, c.ColorName;

IF OBJECT_ID('tempdb..#RRMaterialVotes') IS NOT NULL DROP TABLE #RRMaterialVotes;
SELECT t.ReferenceNumber, cm.CaseMaterialName, COUNT(*) AS VoteCount
INTO #RRMaterialVotes
FROM #RRWatchCore AS t WITH (NOLOCK)
JOIN dbo.tblWatchToCaseMaterial_d AS wcmd WITH (NOLOCK) ON wcmd.WatchId = t.WatchId
JOIN dbo.tblCaseMaterial AS cm WITH (NOLOCK) ON cm.CaseMaterialId = wcmd.CaseMaterialId
GROUP BY t.ReferenceNumber, cm.CaseMaterialName;

IF OBJECT_ID('tempdb..#RRModelVotes') IS NOT NULL DROP TABLE #RRModelVotes;
SELECT t.ReferenceNumber, t.ModelName, COUNT(*) AS VoteCount
INTO #RRModelVotes
FROM #RRWatchCore AS t WITH (NOLOCK)
WHERE t.ModelName IS NOT NULL
GROUP BY t.ReferenceNumber, t.ModelName;

IF OBJECT_ID('tempdb..#RawRefBranch') IS NOT NULL DROP TABLE #RawRefBranch;
;WITH TopColor AS (
    SELECT ReferenceNumber, ColorName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, ColorName ASC) AS rn
    FROM #RRColorVotes
),
TopMaterial AS (
    SELECT ReferenceNumber, CaseMaterialName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, CaseMaterialName ASC) AS rn
    FROM #RRMaterialVotes
),
TopModel AS (
    SELECT ReferenceNumber, ModelName,
        ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY VoteCount DESC, ModelName ASC) AS rn
    FROM #RRModelVotes
),
AnyWatch AS (
    SELECT ReferenceNumber, PublishWatchId
    FROM (
        SELECT
            ReferenceNumber, PublishWatchId,
            ROW_NUMBER() OVER (PARTITION BY ReferenceNumber ORDER BY WatchId ASC) AS rn
        FROM #RRWatchCore
    ) AS x
    WHERE rn = 1
)
SELECT
    t.ReferenceNumber,
    DialColor = MAX(tc.ColorName),
    CaseMaterial = MAX(tm.CaseMaterialName),
    ModelName = MAX(tmo.ModelName),
    PublishWatchId = MAX(aw.PublishWatchId),
    Images = STRING_AGG(t.PrimaryImage, ', ') WITHIN GROUP (ORDER BY t.WatchId)
INTO #RawRefBranch
FROM #RRWatchCore AS t WITH (NOLOCK)
LEFT JOIN TopColor AS tc ON tc.ReferenceNumber = t.ReferenceNumber AND tc.rn = 1
LEFT JOIN TopMaterial AS tm ON tm.ReferenceNumber = t.ReferenceNumber AND tm.rn = 1
LEFT JOIN TopModel AS tmo ON tmo.ReferenceNumber = t.ReferenceNumber AND tmo.rn = 1
LEFT JOIN AnyWatch AS aw ON aw.ReferenceNumber = t.ReferenceNumber
GROUP BY t.ReferenceNumber;

-- ---------- Final combined output ----------
-- Only two branches now -- Catalog-sourced refs are folded into
-- #EveryWatchBranch (see above), so there's no separate catalog-side result set.
SELECT ReferenceNumber, DialColor, CaseMaterial, ModelName, PublishWatchId, Images FROM #EveryWatchBranch
UNION ALL
SELECT ReferenceNumber, DialColor, CaseMaterial, ModelName, PublishWatchId, Images FROM #RawRefBranch
ORDER BY ReferenceNumber;

-- ============================================================
-- All distinct non-empty RawReferenceNumber values for ManufacturerId = 23
-- (raw values as stored, not tokenized/split)
-- ============================================================
SELECT DISTINCT
    wd.RawReferenceNumber
FROM EveryWatch.dbo.tblWatch_d AS wd WITH (NOLOCK)
WHERE wd.ManufacturerId = 23
  AND wd.RawReferenceNumber IS NOT NULL
  AND LTRIM(RTRIM(wd.RawReferenceNumber)) <> ''
ORDER BY wd.RawReferenceNumber;

-- ============================================================
-- From #rawrefs, keep only distinct RawReferenceNumber values that
-- contain at least one digit anywhere in them
-- ============================================================
SELECT DISTINCT r.RawReferenceNumber
FROM #rawrefs AS r WITH (NOLOCK)
WHERE r.RawReferenceNumber LIKE '%[0-9]%';

-- ============================================================
-- Same, but with comma-separated WatchIds associated to each
-- digit-containing RawReferenceNumber (joined back to #watch)
-- ============================================================
SELECT
    w.RawReferenceNumber,
    STRING_AGG(w.WatchId, ', ') AS WatchIds
FROM #watch AS w WITH (NOLOCK)
WHERE w.RawReferenceNumber LIKE '%[0-9]%'
GROUP BY w.RawReferenceNumber;

-- ============================================================
-- For #temp ReferenceNumbers with more than one CatalogId,
-- show the comma-separated list of CatalogIds assigned to each
-- ============================================================
SELECT
    t.ReferenceNumber,
    STRING_AGG(t.CatalogId, ', ') AS CatalogIds,
    MAX(t.CatalogId) AS CatalogId
INTO #todelete
FROM #temp AS t WITH (NOLOCK)
GROUP BY t.ReferenceNumber
HAVING COUNT(t.CatalogId) > 1;

SELECT * FROM #todelete;

-- ============================================================
-- Check tbl_CAT_Model_d for duplicate active models after clean-naming
-- (same ManufacturerId + ModelName, StatusID = 1 only)
-- ============================================================
SELECT
    m.ManufacturerId,
    LTRIM(RTRIM(m.ModelName)) AS ModelName,
    COUNT(*) AS DupCount,
    STRING_AGG(m.ModelId, ', ') AS ModelIds
FROM dbo.tbl_CAT_Model_d AS m WITH (NOLOCK)
WHERE m.StatusID = 1
GROUP BY m.ManufacturerId, LTRIM(RTRIM(m.ModelName))
HAVING COUNT(*) > 1
ORDER BY m.ManufacturerId, ModelName;

Select *
From tbl_CAT_Embelishment_d (NOLOCK)

-- ============================================================
-- tbl_RE_DiscardedWatch: top 100 WatchIds (desc) per 0.01-wide
-- ImageMatchScore band between 0.70 and 0.97
-- (0.70-0.71, 0.71-0.72, ..., 0.96-0.97)
-- ============================================================
IF OBJECT_ID('tempdb..#cartier') IS NOT NULL DROP TABLE #cartier;
SELECT wd.WatchId, wd.ReferenceEnrichmentId, wd.ReferenceNumberId
INTO #cartier
FROM tblWatch_d AS wd WITH (NOLOCK)
WHERE wd.ManufacturerId = 23 AND wd.IsDeleted = 0;

IF OBJECT_ID('tempdb..#DiscardedBanded') IS NOT NULL DROP TABLE #DiscardedBanded;
SELECT
    twer.*,
    FLOOR(twer.ImageMatchScore * 100) / 100.0 AS BandStart,
    ROW_NUMBER() OVER (
        PARTITION BY FLOOR(twer.ImageMatchScore * 100)
        ORDER BY twer.WatchId DESC
    ) AS rn
INTO #DiscardedBanded
FROM tbl_RE_DiscardedWatch AS twer WITH (NOLOCK)
JOIN #cartier AS c WITH (NOLOCK) ON twer.WatchId = c.WatchId
WHERE twer.ImageMatchScore >= 0.70 AND twer.ImageMatchScore <= 0.97;

-- Cap to the top 100 per band FIRST, so every downstream join only
-- touches this small capped set instead of the whole banded table.
IF OBJECT_ID('tempdb..#TopBanded') IS NOT NULL DROP TABLE #TopBanded;
SELECT b.*
INTO #TopBanded
FROM #DiscardedBanded AS b WITH (NOLOCK)
WHERE b.rn <= 100;

-- Reference number lookup (via #cartier -> tblReferenceNumber), keyed on the capped set only
IF OBJECT_ID('tempdb..#TopRefNumbers') IS NOT NULL DROP TABLE #TopRefNumbers;
SELECT
    t.WatchId,
    c.ReferenceEnrichmentId,
    rn2.ReferenceNumber
INTO #TopRefNumbers
FROM #TopBanded AS t WITH (NOLOCK)
JOIN #cartier AS c WITH (NOLOCK) ON t.WatchId = c.WatchId
LEFT JOIN tblReferenceNumber AS rn2 WITH (NOLOCK) ON c.ReferenceNumberId = rn2.ReferenceNumberId;

-- Primary image URL, keyed on the capped set only
IF OBJECT_ID('tempdb..#TopPrimaryImage') IS NOT NULL DROP TABLE #TopPrimaryImage;
SELECT
    t.WatchId,
    mad.Url
INTO #TopPrimaryImage
FROM #TopBanded AS t WITH (NOLOCK)
LEFT JOIN tblMediaAsset_d AS mad WITH (NOLOCK) ON t.WatchId = mad.WatchId AND mad.IsPrimary = 1;

-- Enrichment media asset, keyed on the distinct ReferenceEnrichmentIds of the capped set only
IF OBJECT_ID('tempdb..#TopEnrichmentMedia') IS NOT NULL DROP TABLE #TopEnrichmentMedia;
SELECT
    r.WatchId,
    trrema.Original
INTO #TopEnrichmentMedia
FROM #TopRefNumbers AS r WITH (NOLOCK)
LEFT JOIN tbl_RE_ReferenceEnrichmentMediaAsset AS trrema WITH (NOLOCK) ON r.ReferenceEnrichmentId = trrema.ReferenceEnrichmentId;

-- Final combine -- all joins below are 1:1 (or 1:small) against the already-capped WatchId set
SELECT
    t.*,
    rn.ReferenceEnrichmentId,
    rn.ReferenceNumber,
    pi.Url,
    em.Original
FROM #TopBanded AS t WITH (NOLOCK)
LEFT JOIN #TopRefNumbers AS rn WITH (NOLOCK) ON t.WatchId = rn.WatchId
LEFT JOIN #TopPrimaryImage AS pi WITH (NOLOCK) ON t.WatchId = pi.WatchId
LEFT JOIN #TopEnrichmentMedia AS em WITH (NOLOCK) ON t.WatchId = em.WatchId
ORDER BY t.BandStart, t.WatchId DESC;